#!/usr/bin/env python3
"""Generate the run-dependent inputs of the PML pulse case from the
environment set by prepareCase. Run after 0.orig has been restored to 0."""
import json
import os
from pathlib import Path

CASE = Path(__file__).resolve().parent


def env(name, kind=float):
    return kind(os.environ[name])


def write(path, text):
    (CASE / path).write_text(text)


HEADER = """FoamFile
{{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      {object};
}}

// Generated by prepare_pml.py.

"""


def block_mesh(dim, half, n):
    zh = half if dim == 3 else 0.5 * 2 * half / n
    nz = n if dim == 3 else 1
    v = [(-half, -half, -zh), (half, -half, -zh), (half, half, -zh),
         (-half, half, -zh), (-half, -half, zh), (half, -half, zh),
         (half, half, zh), (-half, half, zh)]
    walls = ["(0 4 7 3)", "(1 2 6 5)", "(0 1 5 4)", "(3 7 6 2)"]
    front = ["(0 3 2 1)", "(4 5 6 7)"]
    if dim == 3:
        walls += front
    text = HEADER.format(object="blockMeshDict")
    text += "vertices\n(\n" + "".join(
        f"    ({x!r} {y!r} {z!r})\n" for x, y, z in v) + ");\n\n"
    text += (f"blocks\n(\n    hex (0 1 2 3 4 5 6 7) ({n} {n} {nz}) "
             "simpleGrading (1 1 1)\n);\n\n")
    text += "boundary\n(\n    walls\n    {\n        type wall;\n        faces\n        (\n"
    text += "".join(f"            {f}\n" for f in walls) + "        );\n    }\n"
    if dim == 2:
        text += ("    frontAndBack\n    {\n        type empty;\n        faces\n"
                 "        (\n" + "".join(f"            {f}\n" for f in front)
                 + "        );\n    }\n")
    return text + ");\n"


def main():
    dim = env("DIM", int)
    if dim not in (2, 3):
        raise SystemExit("DIM must be 2 or 3")
    enlarged = env("ENLARGED", int) == 1
    a = env("HALF_WIDTH")
    pml = 0.0 if enlarged else env("PML_THICKNESS")
    half = env("ENLARGED_HALF_WIDTH") if enlarged else a + pml
    n = round(2 * half / env("CELL_SIZE"))
    h = 2 * half / n
    c_g = env("CG")
    dt = env("COURANT") * h / c_g
    n_steps = round(env("END_TIME") / dt)
    stride = max(1, round(env("SAMPLE_INTERVAL") / dt))
    source = [float(v) for v in os.environ["SOURCE"].split()]
    s = env("PULSE_WIDTH")
    radius = env("DROP_RADIUS")

    write("system/blockMeshDict", block_mesh(dim, half, n))

    zbox = half if dim == 3 else 10.0
    write("constant/transportProperties", HEADER.format(
        object="transportProperties") + f"""rhol            {os.environ['RHOL']};
cl              {os.environ['CL']};
rhog            {os.environ['RHOG']};
cg              {c_g};
kg              #eval{{1.0/($rhog*$cg*$cg)}};
kl              #eval{{1.0/($rhol*$cl*$cl)}};

// Reference frequency of the pulse spectrum; the radiation average is not
// used here, so its window is kept short.
f               {c_g / (2 * 3.141592653589793 * s)!r};
radiationAveragePeriods 0.1;

timeIntegrationMethod {os.environ['TIME_METHOD']};
timeIntegrationTheta  {os.environ['THETA']};
timeBlockLinearSolver {os.environ['BLOCK_SOLVER']};
segregatedImplicitPMLDamping {'true' if env('SEGREGATED_IMPLICIT_DAMPING', int) else 'false'};
acousticDampingRate   0;

// Cartesian PML of thickness L inside the box, read by setPMLFields.
PMLType         rectangle;
L               {pml if pml > 0 else 1e-9!r};
sigmaMax        {0.0 if enlarged else env('SIGMA_MAX')!r};
po              {os.environ['PML_ORDER']};
PMLMax          ({half!r} {half!r} {zbox!r});
PMLMin          ({-half!r} {-half!r} {-zbox!r});
""")

    # Maxima over the whole domain, PML included, come from probes at every
    # cell: fieldMinMax would load libgeometricVoF a second time (duplicate
    # isoAlpha reconstruction scheme) and abort the solver at exit.
    domain_probes = "" if env("DOMAIN_PROBES", int) == 0 else f"""    domainProbes
    {{
        type            probes;
        libs            (sampling);
        writeControl    timeStep;
        writeInterval   {stride};
        writePrecision  6;
        fields          (p v u);
        #include        "domainProbeLocations"
    }}
"""

    cell_probes = "" if env("PHYSICAL_PROBES", int) == 0 else f"""    // Physical-domain cells only; domainProbes covers the PML.
    cellProbes
    {{
        type            probes;
        libs            (sampling);
        writeControl    timeStep;
        writeInterval   {stride};
        writePrecision  10;
        fields          (p pDot U);
        #include        "probeLocations"
    }}
"""

    write("system/controlDict", HEADER.format(object="controlDict") + f"""application     {os.environ['SOLVER']};
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         {n_steps * dt!r};
deltaT          {dt!r};
writeControl    runTime;
writeInterval   {n_steps * dt!r};
purgeWrite      0;
writeFormat     ascii;
writePrecision  10;
writeCompression off;
timeFormat      general;
timePrecision   12;
runTimeModifiable no;
adjustTimeStep  no;

functions
{{
{cell_probes}{domain_probes}}}
""")

    centre = (" + ".join(f"sqr(pos().{c}() - {x!r})"
                         for c, x in zip("xyz", source)))
    write("system/setExprFieldsDict", HEADER.format(object="setExprFieldsDict")
          + f"""expressions
(
    p
    {{
        field       p;
        expression  #{{ {env('P0')!r}*exp(-({centre})/{2 * s * s!r}) #}};
    }}
);
""")
    if radius > 0:
        shape = ("type cylinder;\ndirection (0 0 1);\n" if dim == 2
                 else "type sphere;\n")
        write("system/setAlphaFieldDict", HEADER.format(
            object="setAlphaFieldDict")
            + f"field alpha.water;\n{shape}origin (0 0 0);\nradius {radius!r};\n")

    centres = [-half + (i + 0.5) * h for i in range(n)]
    all_z = centres if dim == 3 else [0.0]
    write("system/domainProbeLocations", "probeLocations\n(\n" + "".join(
        f"    ({x!r} {y!r} {z!r})\n" for z in all_z for y in centres
        for x in centres) + ");\n")
    inside = [x for x in centres if abs(x) < a]
    zs = inside if dim == 3 else [0.0]
    points = [(x, y, z) for z in zs for y in inside for x in inside]
    write("system/probeLocations", "probeLocations\n(\n" + "".join(
        f"    ({x!r} {y!r} {z!r})\n" for x, y, z in points) + ");\n")

    setup = {
        "dim": dim, "enlarged": enlarged, "halfWidth": a, "domainHalfWidth": half,
        "pmlThickness": pml, "sigmaMax": 0.0 if enlarged else env("SIGMA_MAX"),
        "pmlOrder": env("PML_ORDER"), "n": n, "h": h, "nPhysical": len(inside),
        "rhoG": env("RHOG"), "cG": c_g, "rhoL": env("RHOL"), "cL": env("CL"),
        "dropRadius": radius, "p0": env("P0"), "pulseWidth": s,
        "source": source, "courant": env("COURANT"), "deltaT": dt,
        "nSteps": n_steps, "endTime": n_steps * dt, "probeStride": stride,
        "method": os.environ["TIME_METHOD"], "theta": env("THETA"),
        "blockSolver": os.environ["BLOCK_SOLVER"],
        "domainProbes": env("DOMAIN_PROBES", int) == 1,
        "segregatedImplicitDamping": env("SEGREGATED_IMPLICIT_DAMPING", int) == 1,
    }
    write("caseSetup.json", json.dumps(setup, indent=2) + "\n")
    print(f"{dim}D {'enlarged' if enlarged else 'PML'}: {n}^{dim} cells, "
          f"h = {h * 1e3:.4g} mm, s/h = {s / h:.3g}, dt = {dt:.4g} s, "
          f"{n_steps} steps, sigma_max dt = {setup['sigmaMax'] * dt:.3g}, "
          f"{len(points)} probes")


if __name__ == "__main__":
    main()
